INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (1,'english','easy','short','The quick brown fox jumps over the lazy dog',NULL,NULL),
	 (2,'english','easy','short','Farmer Jack realized that big yellow quilts were expensive.',NULL,NULL),
	 (3,'english','normal','medium','Five jumping wizards hex bolty quick. Jacky can now give six big tips from the old quiz ',NULL,NULL),
	 (4,'english','normal','medium','Is the milk cold, or still hot? Tom hasn''t had anything to eat since breakfast.',NULL,NULL),
	 (5,'english','hard','long','She''s got eyes of the bluest skies As if they thought of rain I''d hate to look into those eyes and see an ounce of pain Her hair reminds me of a warm, safe place Where, as a child, I''d hide And pray for the thunder and the rain to quietly pass me by',NULL,NULL),
	 (6,'english','hard','long','They decided to plant a tree in the backyard to celebrate the start of spring. Your name isn''t you. That is also just a letter code that identifies you. If you''re one of those people who hates staying home on the weekend, check out the local bowling alley. ',NULL,NULL),
	 (7,'russian','easy','short','Завтра будет солнечно, временами дожди.',NULL,NULL),
	 (8,'russian','easy','short','Созрев, фрукт падает с дерева.',NULL,NULL),
	 (9,'russian','easy','short','Съешь же ещё этих мягких французских булок да выпей чаю.',NULL,NULL),
	 (10,'russian','normal','medium','Вступив в бой с шипящими змеями - эфой и гадюкой, - маленький, цепкий, храбрый ёж съел их. ',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (11,'russian','normal','medium','Широкая электрификация южных губерний даст мощный толчок подъёму сельского хозяйства.',NULL,NULL),
	 (12,'russian','hard','long','Елизавета Вторая правила в течение семидесяти лет. Она умерла в возрасте девяноста шести лет. Наследником престола стал её сын Чарльз, объявленный престолонаследником в 1952 году и взявший имя Карл Третий. Он был в очереди на престол в течение семи десятилетий, что стало самым долгим ожиданием престола в истории британской монархии.',NULL,NULL),
	 (13,'russian','hard','long','Дайте человеку необходимое и он захочет удобств. Обеспечьте его удобствами - он будет стремиться к роскоши. Осыпьте его роскошью - он начнет вздыхать по изысканному. Позвольте ему получать изысканное и он возжаждет безумств. Одарите его всем, что он пожелает - он будет жаловаться, что его обманули и что он получил совсем не то, что хотел.',NULL,NULL),
	 (14,'english','easy','short','We need to stay focused on our goals.',NULL,NULL),
	 (15,'english','easy','short','It''s clear that Tom is unhappy here.',NULL,NULL),
	 (16,'english','easy','short','Do you want to know what''s happening? I''m struggling to cope with it all.',NULL,NULL),
	 (17,'english','easy','short','The adventurers were promised untold wealth and glory. My sister is a secretary at a bank. Aluminum foil is more expensive than plastic wrap.',NULL,NULL),
	 (18,'english','easy','short','I''m not hungry. I just had breakfast.',NULL,NULL),
	 (19,'english','easy','short','The beginning of a new year is a time to be hopeful for the future.',NULL,NULL),
	 (20,'english','easy','short','What would you do if you found a worm in an apple you were eating?',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (21,'english','easy','short','If you could time travel, would you go to the past or to the future?',NULL,NULL),
	 (22,'english','easy','short','What a surprise! I never thought I''d meet you in a place like this.',NULL,NULL),
	 (23,'english','easy','short','There isn''t a day that goes by that I don''t think of you.',NULL,NULL),
	 (24,'english','easy','short','What''s the first thing you do in the morning after getting out of bed?',NULL,NULL),
	 (25,'english','easy','short','If you could choose any place in the world to retire, where would you choose?',NULL,NULL),
	 (26,'english','easy','short','No matter what you say, you won''t be able to change Tom''s mind.',NULL,NULL),
	 (27,'english','easy','short','Where were you on October 20th between 2:00 and 6:00 in the morning?',NULL,NULL),
	 (28,'english','easy','short','George Frideric Handel, Johann Sebastian Bach and Giuseppe Domenico Scarlatti were all born in 1685.',NULL,NULL),
	 (29,'english','easy','short','I have trouble remembering what I need to do, so I always write things down.',NULL,NULL),
	 (30,'english','easy','short','If I''d had enough time, I would''ve been able to finish this yesterday.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (31,'english','easy','short','It''s been a long time since I''ve put new strings on my guitar.',NULL,NULL),
	 (32,'english','easy','short','Mary was surprised to see a cat''s wet paw prints in her living room.',NULL,NULL),
	 (33,'english','easy','short','This cactus looks soft and fuzzy, but you shouldn''t touch it because its spines are very sharp and will get stuck in your hand.',NULL,NULL),
	 (34,'english','easy','short','I don''t think that it''s necessary for me to sound like a native speaker. I just want to be able to speak fluently.',NULL,NULL),
	 (35,'english','easy','short','People tend to only compliment you on your language ability when it''s apparent that you still don''t quite sound like a native speaker.',NULL,NULL),
	 (36,'english','easy','short','The police drew an outline of a body at the scene of the crime to indicate how the body was lying when it was found.',NULL,NULL),
	 (37,'english','easy','short','I don''t know if this is a problem that can be solved, but it might be something we should be trying to figure out.',NULL,NULL),
	 (38,'english','easy','short','And the good news is that today the economy is growing again. Wages, incomes, home values and retirement accounts are all rising again. Poverty is falling again.',NULL,NULL),
	 (39,'english','easy','short','If one has the right to live, then one should also have the right to die. If not, then living is not a right, but an obligation.',NULL,NULL),
	 (40,'english','easy','short','Will we accept an economy where only a few of us do spectacularly well? Or will we build an economy where everyone who works hard has a chance to get ahead?',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (41,'english','easy','short','If you don''t want to put on sunscreen, that''s your problem. Just don''t come complaining to me when you get a sunburn.',NULL,NULL),
	 (42,'english','easy','short','From time to time, a proposal to pull down a much-loved old building to make room for a new block of flats raises a storm of angry protest.',NULL,NULL),
	 (43,'english','easy','short','Go to work, send your kids to school. Follow fashion, act normal, walk on the pavements, watch TV. Save for your old age. Obey the law. Repeat with me: I am free.',NULL,NULL),
	 (44,'english','normal','medium','His eyes were as red burning coals; long grey hair fell over his shoulders in matted coils; his garments, which were of antique cut, were soiled and ragged, and from his wrists and ankles hung heavy manacles and rusty gyves.',NULL,NULL),
	 (48,'english','easy','short','I can''t remember all my passwords, so I write them all down in a notebook that I keep hidden where I don''t think that anyone can find it.',NULL,NULL),
	 (49,'english','easy','short','The people here are particular about what they eat, so even if a restaurant is inexpensive, it''ll soon go out of business if the food doesn''t taste good.',NULL,NULL),
	 (50,'english','easy','short','You can fool some of the people all of the time, and all of the people some of the time, but you can''t fool all of the people all of the time.',NULL,NULL),
	 (51,'english','easy','short','How beautiful it is to be alive! I know what that is like. But what would it be like to stop thinking once and for all, to cease to exist?',NULL,NULL),
	 (52,'english','easy','short','"Why do we still have this button? We should just throw it into trash." "We can do that, but first I''m going to make lots of spaghetti for dinner."',NULL,NULL),
	 (53,'english','easy','short','Our forefathers would not have given the name of Senate to our supreme council if they did not see in the elders the virtues of prudence, common sense and reason.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (54,'english','easy','short','"Why didn''t you ring us? You know we would''ve come and picked you up from the station!" "It was meant to be a surprise that I came early."',NULL,NULL),
	 (55,'english','easy','short','You have to be brave to be an actor. It''s not easy to perform on stage in front of a lot of people. I am too shy for that.',NULL,NULL),
	 (56,'english','easy','short','Scientists say that a woodpecker’s brain is able to withstand g-forces of 1,200 G’s from the repeated impacts and deceleration brought on by this rapid pecking.',NULL,NULL),
	 (57,'english','easy','short','In May of 1865, Brazil, Uruguay, and Argentina signed the Triple Alliance Treaty that set the objectives of the war and conditions for surrender that they would impose upon Paraguay.',NULL,NULL),
	 (58,'english','easy','short','Those who know nothing but the countryside have no sense of countryside, and those who have not set foot outside the city do not know what a city really is.',NULL,NULL),
	 (59,'english','easy','short','There is no single room available at present, I''m afraid, but you could have a double room at a slightly reduced rate unless you want two breakfasts, of course.',NULL,NULL),
	 (60,'english','easy','short','When the last tree is cut down, when the last river is poisoned, when the last bird is caught, - only then will you realize that money can not be eaten.',NULL,NULL),
	 (61,'english','easy','short','Money''s always to be found when we need to send men to be killed on the border; but there''s none left when it comes time to help them.',NULL,NULL),
	 (62,'english','easy','short','If you paint it yellow, you''ll kill two birds with one stone: it''ll stand out, and you''ll save money because you can use paint you already have.',NULL,NULL),
	 (63,'english','easy','short','In 1912, the Austrian tailor Franz Reichelt died jumping off the first floor of the Eiffel Tower while trying out his new invention, the parachute coat, which did not work...',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (64,'english','easy','short','The queen is the most powerful piece. Second to the queen is the rook. The bishop and the knight have approximately the same value. The pawn has the lowest relative value.',NULL,NULL),
	 (65,'english','normal','medium','Plenty of snow had fallen overnight. In the streets the next morning, grandmothers appeared with their grandchildren on sledges, and in the park that afternoon, after school, snowball fights broke out.',NULL,NULL),
	 (66,'english','easy','short','The money spent by Brazil on the construction of the stadiums for the FIFA World Cup in 2014 already exceeded what Germany spent in 2006 and South Africa in 2010 combined.',NULL,NULL),
	 (67,'english','easy','short','Autumn came, and the leaves in the forest turned to orange and gold. Then, as winter approached, the wind caught them as they fell and whirled them in the cold air.',NULL,NULL),
	 (69,'russian','easy','short','Бразилия, Уругвай и Аргентина подписали в мае 1865 года соглашение о Тройственном союзе, в котором были отмечены цели войны и условия капитуляции, установленные для Парагвая.',NULL,NULL),
	 (70,'russian','easy','short','Когда Том не может заснуть, он начинает считать горностаев. Это его быстро умиротворяет, и, не успев досчитать и до пятидесятого горностая, он уже крепко спит.',NULL,NULL),
	 (71,'russian','easy','short','Когда будет срублено последнее дерево, когда будет отравлена последняя река, когда будет поймана последняя птица, - только тогда вы поймете, что деньги нельзя есть.',NULL,NULL),
	 (72,'russian','easy','short','Когда нужно послать кого-то на смерть в пограничном конфликте, деньги всегда находятся. Но их не остаётся, когда приходит время помогать посланным.',NULL,NULL),
	 (73,'russian','easy','short','Если это покрасишь жёлтым, убьёшь двух зайцев одним выстрелом - и будет бросаться в глаза, и сэкономишь деньги, потому что сможешь использовать краску, которая у тебя уже есть.',NULL,NULL),
	 (74,'russian','easy','short','В 1912 году австрийский портной Франц Райхельт погиб, спрыгнув с первого уровня Эйфелевой башни, при попытке испытать своё изобретение - плащ-парашют, который не раскрылся.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (75,'russian','easy','short','Ферзь – самая сильная фигура. За ним следует ладья. Слон и конь ценятся примерно одинаково. Пешка обладает наименьшей относительной ценностью.',NULL,NULL),
	 (76,'russian','easy','short','Ночью шёл сильный снег. На следующее утро на улицах появились бабушки со своими внуками на санках, а во второй половине дня после школы начались игры в снежки в парке.',NULL,NULL),
	 (77,'russian','normal','medium','Сумма средств, потраченных Бразилией на строительство стадионов к чемпионату мира по футболу 2014 года, уже превысила сумму, потраченную Германией и Южной Африкой вместе взятыми, в 2006 и 2010 годах, соответственно.',NULL,NULL),
	 (78,'russian','easy','short','Осень пришла, и листья в лесу стали оранжевыми и золотыми. Затем, с приближением зимы, ветер ловил их, когда они падали, и кружил в холодном воздухе.',NULL,NULL),
	 (80,'russian','easy','short','Очевидно, что американцы не могут решить даже свои собственные проблемы, почему они тогда думают, что способны решать проблемы других стран?',NULL,NULL),
	 (81,'russian','easy','short','Он зажег свет и схватил свой меч; тогда он поспешил к мальчикам, но когда пришел на место, то увидел странную вещь, ибо Геракл смеялся и показывал мертвых змей.',NULL,NULL),
	 (82,'russian','normal','medium','Существует ли вкусовой или кулинарный аналог рассказа или фильма? Иными словами, возможно ли съесть или попробовать на вкус завершенную, захватывающую историю подобно тому, как ее можно прочитать или увидеть на экране?',NULL,NULL),
	 (83,'russian','easy','short','Гон, маленький одинокий лисёнок, жил в норе, вырытой в густо поросшем папоротником лесу. И ночью, и днём наведывался он в соседнюю деревню и только и делал, что шалил там.',NULL,NULL),
	 (84,'russian','easy','short','Мечась между двумя мнениями, я то думаю, что то, что нам удалось вырваться из пределов атмосферы и ходить по луне, – чистое безумие, то думаю, как жаль, что это оказалось так скучно.',NULL,NULL),
	 (85,'russian','normal','medium','В игре Го два игрока по очереди кладут белые и черные камни на изначально пустую доску, чтобы гарантировать владение местами на игровом поле. Побеждает игрок, достигший наибольшего территориального завоевания.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (86,'russian','easy','short','Главная тайна мыслей - откуда они берутся? Ведь невозможно уловить мысль, пока она не появится в голове. Поэтому я принимаю собственные мысли как дар, которым счастлив воспользоваться.',NULL,NULL),
	 (87,'russian','normal','medium','В тот момент, когда наша экономика растёт, наши предприятия создают рабочие места наибольшими темпами, начиная с 90-х годов, а зарплаты снова начинают расти, мы должны принять ряд решений относительно того, какой страной мы хотим быть.',NULL,NULL),
	 (88,'russian','easy','short','Я давно понял одно: злость затмевает разум. Многие из тех, кого я лично знаю, на моих глазах становились в злобе безрассудными зверями, и эти твои речи - не исключение. Старайся остаться спокойным.',NULL,NULL),
	 (89,'russian','normal','medium','Наполеона помнят за введённый им во Франции "Кодекс Наполеона", который оказал большое влияние на правовые системы других стран. В США, к примеру, законодательство штата Луизиана основано на кодексе Наполеона.',NULL,NULL),
	 (90,'russian','normal','medium','Будучи студентом, Адамс выполнял исследование, пытаясь объяснить причину неравномерностей в движении планеты Уран. Он выдвинул теорию, что отличие её орбиты от ожидаемой может быть вызвано присутствием ещё не открытой планеты.',NULL,NULL),
	 (91,'russian','normal','medium','Моя методика изучения новых слов проста: каждое утро учу по пять новых слов, в первый раз повторяю их перед сном, потом через три дня, потом через неделю, потом через месяц, потом через три месяца и наконец через полгода.',NULL,NULL),
	 (92,'russian','normal','medium','Харон считается спутником (карликовой) планеты Плутон. Однако, так как его диаметр больше, чем половина диаметра самого Плутона, он может рассматриваться как равный партнёр; то есть, Плутон и Харон могут считаться двойной планетой.',NULL,NULL),
	 (93,'russian','normal','medium','Бывают ужасно полезные и в то же время наполненные ошибками книги, а бывают книги без единой ошибки, достоинство которых, похоже, в отсутствии ошибок только и состоит. А еще бывают такие книги, что думаешь, как можно было собрать такое количество такого замечательного материала и написать до такой степени неинтересное, скучное чтиво?',NULL,NULL),
	 (94,'russian','normal','medium','Каждый паук - разносторонний гений: он планирует свою паутину, как архитектор, а затем осуществляет этот план, как искусный ткач. Он также является химиком, который может синтезировать шелк с помощью управляемого компьютером производственного процесса, а затем использовать его для прядения.',NULL,NULL),
	 (95,'russian','easy','short','Я знал, что помимо больших планет, таких как Земля, Юпитер, Марс, Венера, которым мы дали имена, есть также сотни других. И некоторые настолько малы, что их с трудом можно разглядеть в телескоп.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (97,'english','easy','short','It is clear that the Americans can''t even solve their own problems, so how can they possibly think themselves capable of dealing with the rest of the world''s problems?',NULL,NULL),
	 (98,'english','easy','short','He turned on the light and, taking his sword, ran to the boys, but when he got there he saw an amazing thing, for Hercules was laughing showing off the dead serpents.',NULL,NULL),
	 (99,'english','easy','short','Is there some gustatory or culinary analog of a novel or film? In other words, can you eat or taste a complete, riveting story the way you can watch or read one?',NULL,NULL),
	 (100,'english','easy','short','Gon was a solitary little fox who dug and lived in a hole in a forest full of ferns. Night or day, he would come out and visit the neighboring village, where he would get up to nothing but mischief.',NULL,NULL),
	 (101,'english','easy','short','I alternate wildly between thinking that it’s totally crazy that we clawed our way up out of the atmosphere and walked on the moon, and thinking that it’s a shame that it turned out to be so boring.',NULL,NULL),
	 (102,'english','normal','medium','In the game of Go, two players take turns placing white and black stones on an initially empty board to ensure ownership of spaces on the playing field. The winner is the player who has achieved the greatest territorial conquest.',NULL,NULL),
	 (103,'english','easy','short','The main secret of thoughts is where do they come from? It is impossible to catch a thought until it comes to your mind. That''s why I take my own thoughts as a gift that I''m happy to use.',NULL,NULL),
	 (104,'english','normal','medium','At a moment when our economy is growing, our businesses are creating jobs at the fastest pace since the 1990s, and wages are starting to rise again, we have to make some choices about the kind of country we want to be.',NULL,NULL),
	 (105,'english','normal','medium','One thing I learned a long time ago was that anger clouds the mind. I''ve seen a lot of people I know personally transform into irrational beasts when angry, and this rant of yours is no exception. Try to keep calm.',NULL,NULL),
	 (106,'english','normal','medium','Napoleon is remembered for his establishment of France''s Napoleonic Code, which has had a great influence on the legal systems of other countries. In the US, for example, the legal system of the State of Louisiana is based on the Napoleonic Code.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (107,'english','normal','medium','Наполеона помнят за введённый им во Франции "Кодекс Наполеона", который оказал большое влияние на правовые системы других стран. В США, к примеру, законодательство штата Луизиана основано на кодексе Наполеона.',NULL,NULL),
	 (108,'english','normal','medium','My method of learning new words is simple: every morning I learn five new words. At first I review them before going to bed, then in three days, then in a week, in a month, in three months, and finally in six months.',NULL,NULL),
	 (109,'english','normal','medium','Charon is considered to be a satellite of the (dwarf) planet Pluto. However, because its diameter is more than half as large as that of Pluto itself, it can be considered an equal partner; and Pluto and Charon can be considered a double planet.',NULL,NULL),
	 (110,'english','normal','medium','I found one day in school a boy of medium size ill-treating a smaller boy. I expostulated, but he replied: "The bigs hit me, so I hit the babies; that''s fair." In these words he epitomized the history of the human race.',NULL,NULL),
	 (111,'english','normal','medium','Some books are full of mistakes but are surprisingly useful, while others are flawless yet lack any real value beyond just being correct. There are also books where impressive amounts of high-quality material are compiled, yet they still end up incredibly dull and uninteresting.',NULL,NULL),
	 (112,'english','normal','medium','Every spider is a versatile genius: It plans its web like an architect and then carries out this plan like the proficient weaver it is. It is also a chemist who can synthesize silk employing a computer-controlled manufacturing process, and then use the silk for spinning.',NULL,NULL),
	 (113,'english','normal','medium','I knew very well that in addition to the great planets - such as the Earth, Jupiter, Mars, Venus - to which we have given names, there are also hundreds of others, some of which are so small that one has a hard time seeing them through the telescope.',NULL,NULL),
	 (115,'english','normal','medium','Hey, everyone! I should have told you this before you jumped in, but this pool is filled with ferocious alligators and sharks. Don''t worry, they only seem to come out when they sense motion, so... just stay where you are for the next 3 to 17 hours.',NULL,NULL),
	 (116,'english','normal','medium','Richard Krajicek is known as the only player to beat Pete Sampras at Wimbledon between 1993 and 2000. He upset Pistol Pete in straight sets in the quarterfinal en route to winning the 1996 Wimbledon Championships, which came to be the only Grand Slam title in his career.',NULL,NULL),
	 (117,'english','hard','long','"You see," he explained, "I consider that a man''s brain originally is like a little empty attic, and you have to stock it with such furniture as you choose. A fool takes in all the lumber of every sort that he comes across, so that the knowledge which might be useful to him gets crowded out, or at best is jumbled up with a lot of other things, so that he has a difficulty in laying his hands upon it. Now the skilful workman is very careful indeed as to what he takes into his brain attic. He will have nothing but the tools which may help him in doing his work, but of these he has a large assortment, and all in the most perfect order. It is a mistake to think that that little room has elastic walls and can distend to any extent. Depend upon it there comes a time when for every addition of knowledge you forget something that you knew before. It is of the highest importance, therefore, not to have useless facts elbowing out the useful ones."',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (118,'english','hard','long','If you need instructions, check out the enclosed instruction book. If you need instructions on how to check out the enclosed instruction book, check out the enclosed instructions on how to get instructions on how to check out the enclosed instruction book. If you need instructions on how to check out the enclosed instructions, check out the instructions on how to get instructions on how to check out the enclosed instructions on how to get instructions on how to check out the enclosed instruction book. Thank you.',NULL,NULL),
	 (119,'english','hard','long','A state that entrusts its protection to mercenaries will sooner or later perish, as did ancient Rome, whose inhabitants only wanted to eat and entertain themselves, and left the protection of their native land to the Germanic tribes. The latter betrayed their employers as soon as it became profitable. A real, strong enemy retreats only when all the inhabitants of the country are ready to stand up against it.',NULL,NULL),
	 (120,'english','normal','medium','My dog''s name is Belysh. This summer I taught him to put out his paw. Every morning I wake up early and feed him. Then we go for a walk. He defends me from other dogs. When I go bike riding, he runs beside me. He has a friend, her name is Chernyshka. He likes playing with her. Belysh is a very kind and clever dog.',NULL,NULL),
	 (121,'english','normal','medium','The group box "Image Layout" shows different options for displaying the image in the picture box. There are four layouts to choose from. With Center, your image will be centered in the picture box. With Auto size, your image will be auto sized. With Stretch, your image will be resized to the size of the picture box and with Autozoom, your image will be zoomed to the picture box.',NULL,NULL),
	 (122,'english','normal','medium','What harm would it do if I were to go into the garden for a short time and enjoy myself among the trees and flowers, and the singing birds and fluttering butterflies and humming insects, and look at the dew-drops hiding from the sunbeams in the hearts of the roses and lilies, and wander about in the sunshine, instead of remaining all day in this room?',NULL,NULL),
	 (123,'english','normal','medium','Chris Amon is often considered one of the unluckiest Formula One drivers ever. Whenever he was positioned to win a race, bad luck would interfere, ultimately preventing him from scoring a single victory. Amon himself, however, maintained that he counted himself lucky to have survived a decade-long F1 career mostly unscathed, while many of his fellow drivers suffered serious injury or death.',NULL,NULL),
	 (124,'english','normal','medium','One of the reasons Twitter is popular in Japan is a characteristic of Japanese itself: Japanese uses ideograms which enable it to convey more information in just 140 characters than other languages, not counting Chinese. Incidentally, the Japanese version of this sentence is written with exactly 140 characters. How many characters does it take in other languages?',NULL,NULL),
	 (125,'english','normal','medium','Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do: once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it, ''and what is the use of a book,'' thought Alice ''without pictures or conversation?''',NULL,NULL),
	 (126,'english','hard','long','A hundred years after their discovery, the artifacts from Egyptian prehistoric mausoleums will return close to the place where they were found. A huge new museum overlooking the Giza pyramids in Egypt is due to open some of its sections early next year. The exhibit devoted to pharaoh Tutankhamun, known to archeologists as the Golden Boy and in popular culture as King Tut, is expected to draw the most attention.',NULL,NULL),
	 (127,'english','normal','medium','We move from the relative cool of the Garden Court into the warmth of a jungle. Sunlight from outside shines on this thick green world. The light comes through the top of the building. The glass-covered area in the Palm Court is about twenty-eight meters high. We can climb steps to see the palm trees and other growth from above. Or we can ride up in an elevator.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (128,'english','normal','medium','Anywhere else in the world, this would be a fisherman''s dream, rivers so abundant with fish they jump out of the water, and often right into the boat. But these are not the kind of fish that get anglers in the United States excited. They are known as Asian Carp and the explosion of their population in the Illinois River is a concern to large-river ecologist Kevin Irons.',NULL,NULL),
	 (129,'english','hard','long','The farmer grew carrots, cabbage, onions and beetroot. But he found that potatoes grew better than the other vegetables in the combination of sea and fresh water. Mr. Van Rijsselberghe says four kinds of these potatoes were recently sent to Pakistan, where thousands of hectares of land have been damaged by salinization. Farmers in Pakistan will test the Dutch potatoes to see if they can be grown in those fields.',NULL,NULL),
	 (130,'english','hard','long','The United Nations estimates that each one of us uses nearly 140 kilograms of plastic each year. At least 6.4 million metric tons of that plastic has ended up in the oceans. Environmental activist Captain Charles Moore has found that in some areas, plastic outweighs zooplankton - the ocean''s food base - and is entering the food chain. Our reporter talked to Capt. Moore about his efforts to document ocean pollution.',NULL,NULL),
	 (131,'english','hard','long','If you were a sailor before the invention of modern navigational equipment, lighthouses were treasured beacons for wandering seafarers. They once dotted U.S. coastlines. But with advances in navigation equipment, lighthouses have become obsolete and many are no longer used for navigational purposes by major shipping traffic. Many lighthouses are threatened by changes in geography due to erosion and natural disasters, are vandalized, or are in desperate need of repair.',NULL,NULL),
	 (132,'english','hard','long','The term "ballistics" refers to the study of a projectile in motion. Ballistics also refers to the forensic study of bullets, cartridges and firearms in criminal investigations. When a bullet travels through a gun barrel, the bullet''s metal gets worn in a unique pattern by the harder metal of the barrel. Unless there has been some intentional alteration, any bullet fired by a specific gun will show the same marks.',NULL,NULL),
	 (133,'english','hard','long','The newly discovered planet is relatively near us, about 15 light years from Earth. It is not precisely like our home planet, but a bigger cousin, estimated to be six to eight times Earth''s mass, twice the diameter, and so close to its star that it takes less than two days to orbit, making its temperatures oven-like. The star itself is only one-third the mass of our Sun.For 21 days in August, more than 10,000 athletes from around the world will compete in the Summer Olympic Games in Beijing. While they come in pursuit of personal dreams, they will also represent their respective countries. For spectators and supporters from the more than 200 countries participating, the Olympics are a chance to cheer for their countrymen and women. For the athletes themselves, national pride is a powerful motivator.',NULL,NULL),
	 (134,'english','normal','medium','Why, of course, the people don''t want war. Why would some poor slob on a farm want to risk his life in a war when the best that he can get out of it is to come back to his farm in one piece? Naturally, the common people don''t want war; neither in Russia nor in England nor in America, nor for that matter in Germany. That is understood.',NULL,NULL),
	 (135,'english','normal','medium','Mackinac Island, Michigan is the only city in the United States where there are no motorized vehicles of any kind on the streets. It''s been that way since the automobile was banned by city ordinance in 1898. The island''s thousands of tourists go from place to place in horse-drawn taxi cabs. But the island''s commitment to a unique way of life is being threatened by its own success.',NULL,NULL),
	 (136,'english','hard','long','The canal, though its creation was closely tied to the military operations of Gaius Marius, has shown signs of being used beyond its initial military purpose. The stone platforms found south of the structure, as well as commercial pottery and its prolonged use, suggest that the canal was integrated into the port system of Arles, serving as a passage for goods from the Mediterranean to the interior of Gaul. In later centuries, especially during the High Roman Empire, the canal was likely part of the port system known as Fossae Marianae, a set of port facilities documented in Roman itineraries and ancient maps. Its presence was crucial in establishing the link between the city of Arles – which became a Roman colony in 46 BC – and maritime trade, which favored its economic growth and consolidated its role as an important logistical hub.',NULL,NULL),
	 (137,'english','hard','long','The Top 10 Species list is compiled annually by the International Institute for Species Exploration, or IISE. It calls attention to discoveries that are made even as species are going extinct faster than they are identified. From among the 18,000 new species named last year, a committee of taxonomists chose the ones that made the 2015 list. They include a bird-like dinosaur, dubbed the “chicken from Hell,” that was 3.5 meters from beak to tail and weighed as much as 300 kilograms; a spider that lives in the Moroccan desert and can use its gymnastic talents to cartwheel out of danger; a 23-centimeter-long walking stick common in Vietnam; and a colorful sea slug from the Japanese islands that is the missing link between slugs that feed on colonies of tiny stinging jellies and those specializing on corals.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (138,'english','hard','long','The last film in the Lord of the Rings series, The Return of the King debuted in mid-December, and is still showing in U.S. movie theaters. The epic trilogy comes to a close with a final battle for Middle Earth, and Frodo''s heroic effort to cast the ring into the fiery lava of Mount Doom. The soundtrack features several appearances by renowned Irish flutist James Galway. The high tenor voice of actor Billy Boyd, who plays one of the hobbits, is also highlighted, along with an emotional narrative. To coincide with the film''s climax, composer Howard Shore added more operatic elements to the score. The Return of the King also features the song Into The West, written and recorded by former Eurythmics member and Grammy Award-winning singer Annie Lennox.',NULL,NULL),
	 (139,'english','hard','long','It is my 51st birthday today, on the 12th of January of 2017, and I am at the Richmond Public Market with my Apple iPad mini, as I use the free "guest" network. The atrium is decorated with red lanterns for the coming Chinese New Year. I have eaten from Captain Wa a dish of noodles with fried tofu, white glossy fish, and reddish fatty pork skins and meat. I have sipped a glass of cold Sour Green Apple Green Pearl Tea from Peanut''s Bubble Tea. Later, I have a cold Mint Green Tea from QQ Bubble Tea and Coffee. Then from there again, I have a cold Winter Melon Tea. From Peanut''s, I then have a cold Lychee Green Pearl Tea. I sit, as I wait for my doctor''s appointment.',NULL,NULL),
	 (140,'english','hard','long','I travelled to Amsterdam on my own with a big backpack. The quaint canals and the tree-lined streets always make a good photographic theme. There were lots of Indonesian restaurants there. Inside that labyrinth was my hotel, Hotel Kabul. I met an Egyptian traveller there. At a place of many pigeons, I asked a bespectacled South Asian loiterer to take my picture amongst the birds that he was feeding. I visited the Sex Museum. I just liked walking around, looking at the antique buildings. There were a lot of bicyclists. Long ago, in grade school in Canada, I wrote a geography report about the Netherlands, and I learned about their engineering feats of reclaiming land from the water and, of course, the tulips.',NULL,NULL),
	 (141,'english','hard','long','At the molecular level, salt dissolves in water due to electrical charges and due to the fact that both water and salt compounds are polar, with positive and negative charges on opposite sides in the molecule. The bonds in salt compounds are called ionic because they both have an electrical charge-the chloride ion is negatively charged and the sodium ion is positively charged. Likewise, a water molecule is ionic in nature, but the bond is called covalent, with two hydrogen atoms both situating themselves with their positive charge on one side of the oxygen atom, which has a negative charge. When salt is mixed with water, the salt dissolves because the covalent bonds of water are stronger than the ionic bonds in the salt molecules.',NULL,NULL),
	 (142,'english','hard','long','Sam, a rhesus monkey, was one of the most well known monkeys of the space program. His name was an acronym for the U.S. Air Force School of Aviation Medicine at Brooks Air Force Base, Texas. He was launched on December 4, 1959, housed in a cylindrical capsule within the Mercury spacecraft atop a Little Joe rocket in order to test the launch escape system (LES). Approximately one minute into the flight, travelling at a speed of 3685 mph, the Mercury capsule aborted from the Little Joe launch vehicle. After attaining an altitude of 51 miles, the spacecraft landed safely in the Atlantic Ocean. Sam was recovered, several hours later, with no ill effects from his journey.',NULL,NULL),
	 (144,'russian','normal','medium','Слушайте все! Надо было мне сказать это раньше, до того как вы прыгнули, но в этом бассейне полно свирепых аллигаторов и акул. Не волнуйтесь, они начинают шевелиться, только когда чувствуют движение, так что... просто оставайтесь на месте в течение от трёх до семнадцати часов.',NULL,NULL),
	 (145,'russian','normal','medium','Рихард Крайчек известен тем, что это единственный игрок, победивший Пита Сампраса на Уимблдоне между 1993 и 2000. Он неожиданно обыграл Пита-пистолета в трёх сетах в четвертьфинале на пути к титулу Уимблдона-1996, который оказался единственным титулом Большого Шлема в его карьере.',NULL,NULL),
	 (146,'russian','hard','long','"Видите ли, - сказал он, - я считаю, что человеческий мозг изначально подобен маленькому пустому чердаку, который вы должны обставить так, как хотите. Дурак натащит туда всякой рухляди, какая попадётся под руку, и полезные, нужные вещи уже некуда будет всунуть, или в лучшем случае до них среди всей этой завали и не докопаешься. А человек толковый тщательно отбирает то, что он поместит в свой мозговой чердак. Он возьмёт лишь инструменты, которые понадобятся ему для работы, но зато их будет множество, и все он разложит в образцовом порядке. Было бы ошибкой думать, что у этой маленькой комнатки эластичные стены и их можно растягивать сколько угодно. Уверяю вас, придёт время, когда, приобретая новое, вы будете забывать что-то из прежнего. Поэтому крайне важно, чтобы ненужные сведения не вытесняли собой нужных".',NULL,NULL),
	 (147,'russian','hard','long','Если вам нужны инструкции, воспользуйтесь приложенной книгой-руководством. Если вам нужны инструкции, как пользоваться приложенной книгой-руководством, воспользуйтесь приложенными инструкциями о том, как найти инструкции о том, как пользоваться приложенной книгой-руководством. Если вам нужны инструкции о том, как пользоваться приложенными инструкциями, воспользуйтесь приложенными инструкциями о том, как найти инструкции, как пользоваться приложенными инструкциями о том, как найти инструкции о том, как пользоваться приложенной книгой-руководством. Спасибо.',NULL,NULL),
	 (148,'russian','normal','medium','Государство, которое доверит свою защиту наёмникам, рано или поздно погибнет, как погиб Древний Рим, чьи жители хотели только есть и развлекаться, а защиту родной земли оставили германцам. Те предали своих нанимателей, как только это стало выгодно. Настоящий, сильный враг только тогда отступает, когда против него готовы встать все жители страны.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (149,'russian','hard','long','Опция "Расположение" позволяет выбрать режим показа изображения. Есть четыре варианта показа: "отцентрировать", "замостить", "растянуть" и "авторазмер". Вариант "отцентрировать" позволяет показать много копий изображения рядом друг с другом, "растянуть" позволяет привести размер изображения к размеру области показа, а "авторазмер"  -  изменить масштаб изображения в соответствии с размерами области показа.',NULL,NULL),
	 (150,'russian','normal','medium','Мою собаку зовут Белыш. Этим летом я научил его давать лапу. Каждый день я просыпаюсь рано и кормлю его. Потом мы идём гулять. Он защищает меня от других собак. Когда я еду кататься на велосипеде он бежит вместе со мной. У него есть подружка её зовут Чернышка. Он очень любит с ней играть. Белыш очень умная и добрая собака.',NULL,NULL),
	 (151,'russian','normal','medium','Что плохого случилось бы, если бы я, вместо того, чтобы целыми днями торчать в этой комнате, хоть ненадолго вышел в сад и среди деревьев и цветов наслаждался пением птиц, порханием бабочек и мотыльков, жужжанием насекомых, взирал на капельки росы, спрятавшиеся от солнечных лучей в самом сердце роз и лилий, сам побродил под солнцем?',NULL,NULL),
	 (152,'russian','normal','medium','Крис Эймон часто считается одним из самых невезучих гонщиков Формулы-1 в истории. Всякий раз, когда он был близок к победе, его постигала неудача, так и не позволив ему победить хоть однажды. Сам Эймон, однако, всегда говорил, что ему повезло закончить многолетнюю карьеру в Ф-1 почти невредимым, в то время как многие из его коллег-гонщиков получили серьёзные травмы или даже погибли.',NULL,NULL),
	 (153,'russian','normal','medium','Одной из причин популярности Твиттера в Японии является особенность японского языка: этот язык использует идеограммы, благодаря которым возможна передача всего в 140 знаках большего количества информации в сравнении с другими языками, если не считать китайский. Кстати, японская версия этой фразы составляет ровно 140 знаков. Сколько знаков требуется в других языках?',NULL,NULL),
	 (154,'russian','normal','medium','Алиса начала очень скучать: она сидела рядом с сестрой на берегу и ничего не делала. Раза два она заглянула в книгу, которую читала ее сестра, но там не было ни картинок, ни разговоров. "И что за польза от книги, - подумала она, - в которой нет разговоров или картинок?"',NULL,NULL),
	 (155,'russian','normal','medium','Ну разумеется, люди не хотят войны. Зачем какому-нибудь бедняге на ферме хотеть рисковать своей жизнью на войне, когда лучшее, что он может получить в её конце, – вернуться на свою ферму целым? Естественно, простые люди не хотят войны; ни в России, ни в Англии, ни в Америке, ни в Германии тоже. Это понятно.',NULL,NULL),
	 (156,'russian','hard','long','Жизнь подобна реке с истоком и устьем. У каждого из нас своя река. У одного она изгибистая, змеистая, с мелководьем на перекатах, так что приходится брести, а не плыть. У другого - бурная, кипучая, яростно несущая воды, пролетающая сто тысяч вёрст, пока не встретится с другой рекой и не потеряет стремительность, шумливость, после чего спокойно движется вперёд, к устью. Бывают и не реки, а ручейки - короткие и прозрачные, словно жизнь младенца.',NULL,NULL),
	 (157,'russian','hard','long','Союз электронных издателей разработал систему, позволяющую переносить купленные электронные экземпляры книг из одного магазина эл. книг в другой. Так что теперь если у вас возникнет желание начать пользоваться другим сайтом для покупки, вы сможете полностью переместить всю свою библиотеку на него, без необходимости приобретать заново каждую книгу. К сожалению, эта система доступна только в тех магазинах, которые либо состоят в нашем объединении, либо изъявили своё желание присоединиться к этой системе. Надемся, вам понравится эта разработка, ведь удобство для читателей - наш главный принцип!',NULL,NULL),
	 (158,'russian','hard','long','Строить новые города за Полярным кругом? Во-первых, экология меняется, климат меняется. У нас ведь сейчас вопрос, что делать со многими населенными пунктами, которые построены в вечной мерзлоте. Потому что там города же на сваях построены, и сваи эти вбиты в вечную мерзлоту. И второе - на постоянной основе строить новое жилье, новые города, капитальные строения в условиях Крайнего Севера, переселять туда людей - может быть, в каких-то случаях это и имеет смысл, может быть. Но уверяю вас, иногда вахтовый метод - он гораздо более эффективен.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (159,'russian','hard','long','Покамест ему подавались разные обычные в трактирах блюда, как-то: щи с слоёным пирожком, нарочно сберегаемым для проезжающих в течение нескольких неделей, мозги с горошком, сосиски с капустой, пулярку жареную, огурец солёный и вечный слоёный сладкий пирожок, всегда готовый к услугам; покамест ему всё это подавалось, и разогретое и просто холодное, он заставил слугу, или полового, рассказывать всякий вздор о том, кто содержал прежде трактир и кто теперь, и много ли даёт дохода, и большой ли подлец их хозяин; на что половой по обыкновению отвечал: "О, большой, сударь, мошенник".',NULL,NULL),
	 (160,'russian','hard','long','Общий признак делимости целого числа на натуральную степень двойки состоит в следующем: если число, составленное из n последних цифр рассматриваемого числа (в случае, если в нём меньше n цифр - берём всё число целиком), где n - натуральная степень двойки, делится на n-ную степень двойки, то и само рассматриваемое число также на неё делится; в противном случае, если выделенное число не делится на n-ную степень двойки, то исходное число также не делится на неё. Иначе говоря, эти два числа либо оба делятся, либо оба не делятся на данную степень двойки.',NULL,NULL),
	 (161,'russian','hard','long','Через два месяца после ухода в минус, высшее руководство всё же решилось отстранить от должности Томаса Николаевича и назначить на его место нового кандидата. С этого момента пути назад не стало, и театр окончательно и бесповоротно упал в бездну безвыходности. Все дальнейшие назначения на пост руководителя были ещё хуже, так как ни один из последующих кандидатов не был связан ни с театральным искусством, ни с умением руководить. Последний назначенный верхушкой человек, попытался реанимировать театр, но ему не хватило практических знаний и умений, поэтому последняя и поставленная им наспех пьеса оказалась провальной.',NULL,NULL),
	 (162,'russian','hard','long','Мой русский друг выразил опасение, что бег оказывает повышенную нагрузку на позвоночник и вызывает преждевременный износ суставов. К счастью, я могу его успокоить. Мышцы икр действуют как пружины и смягчают удар. Необходимым условием являются тренированные мышцы икр, и именно это достигается бегом. Бег укрепляет и мышцы, окружающие колено, в результате чего снижается нагрузка на коленный сустав. Движение приводит к улучшению циркуляции крови, и это также оказывается полезным для суставов. Необходимо правильно дозировать тренировочные нагрузки. Главное - не переусердствовать!',NULL,NULL),
	 (163,'russian','hard','long','Как работает большинство программ с симлинками при редактировании данных? Если у меня, например, есть json-файл с пользовательскими данными, на который ссылается симлинк, то при добавлении новых данных, обновлении или удалении старых и т. д., что будет происходить? Программа перейдёт по симлинку и отредактирует исходный файл, перезапишет симлинк и создаст на его месте новый файл с пользовательскими данными или вернёт ошибку из-за того, что симлинк данных не содержит и поэтому редактирование невозможно?',NULL,NULL),
	 (164,'russian','hard','long','От наших пользователей приходило множество предложений о том, что добавить в грядущем обновлении. К сожалению, наши ресурсы ограничены, а потому мы составили список из ста самых лучших по нашему мнению идей, из которых будут реализованы только десять. А вот какие именно из них получат реализацию, будете решать именно вы, дорогие пользователи. Завтра в десять часов начнётся голосование, которое продлится ровно три дня, по итогам которого и будут выбраны те самые десять лучших идей.',NULL,NULL),
	 (165,'russian','hard','long','Дегуманизация неизбежно приводит к дегуманизации самих дегуманизаторов, особенно если они сумели дойти до реализации своих угроз и призывов на деле, продемонстрировав жестокое и бесчеловечное поведение. Применение противником тактик дегуманизации регулярно становится предлогом для того, чтобы дегуманизировать противника в ответ, по следующей логике: "Посмотрите, как они бесчеловечны. Они нас за людей не считают! Они безжалостны и не остановятся ни перед чем. Они хотят нас уничтожить. Нельзя жить с такими людьми или вести с ними переговоры"',NULL,NULL),
	 (166,'russian','hard','long','Ну, так-то оно так, но это работает только здесь, в этой вселенной. А во многих других вселенных это утверждение уже может быть ложным, если там вообще может существовать такое понятие, как правда или ложь. Хотя, наверное, нам с тобой этого узнать не суждено. Да и, в общем-то, какая разница, у меня и в этом-то мире дел невпроворот, так что, думаю, заботиться ещё и о проблемах другого мира мне как-то рановато.',NULL,NULL),
	 (167,'russian','hard','long','После этого скандала его самоуверенность немного поутихла, но уже через месяц Томас Николаевич принял одно из худших решений, которое только мог. Им был составлен и подписан документ, в котором требовалось прекратить показ всех популярных пьес и заменить их на те, что особой известности среди широкой публики не возымели. Также, в день подписания документа Томас Николаевич заявил, что в рекордные два месяца театром будет составлена и отрепетирована новая программа, состоящая из пяти новых и трёх старых позиций.',NULL,NULL),
	 (168,'russian','hard','long','Повторяю. Не покидайте помещения, в котором находитесь. Закройте все окна и двери. Если в вашем помещении имеется хотя бы одна дыра больше, чем десять на тридцать сантиметров измените своё местоположение на более безопасное. Что бы сейчас не находилось в городе, оно обладает невероятной скоростью и жаждой убийств, но не способно проникать в замкнутые пространства, в которые нет проходов его размера. Скорость этого существа явно в несколько раз превышает звуковую. Если хотите жить, воздержитесь от любых посещений улицы.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (170,'russian','easy','short','На португальском языке говорят в девяти странах мира.',NULL,NULL),
	 (171,'russian','easy','short','Врач - это, пожалуй, самая сложная и ответственная профессия.',NULL,NULL),
	 (172,'russian','easy','short','Не забудьте взять солнечные очки на всякий случай.',NULL,NULL),
	 (173,'russian','easy','short','Они обсудили отношения между странами на глобальном форуме.',NULL,NULL),
	 (174,'russian','easy','short','Это был заход солнца в красной марсианской пустыне.',NULL,NULL),
	 (175,'russian','easy','short','В эсперанто существительные, прилагательные, наречия и глаголы показывают свою функцию в предложении с помощью окончаний.',NULL,NULL),
	 (176,'russian','easy','short','Сколько бы раз я ни перечитывал эту книгу, я открываю для себя что-то новое.',NULL,NULL),
	 (177,'russian','easy','short','Поехать из Сан-Паулу в Буэнос-Айрес на машине? Это больше двух тысяч километров пути!',NULL,NULL),
	 (178,'russian','easy','short','На улице сильный ветер и снег, переходящий в дождь. Не самое подходящее время для прогулок!',NULL,NULL),
	 (179,'russian','easy','short','Знаки препинания в двух предложениях могут быть разными, но смысл этих предложений может быть одинаков.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (180,'russian','easy','short','Изучением правильного устройства города занимается специальная дисциплина - градостроительство, которая изучает законы и правила устройства городов.',NULL,NULL),
	 (181,'russian','easy','short','Ростов и Ростов-на-Дону - это два разных города, расположенных достаточно далеко друг от друга.',NULL,NULL),
	 (182,'russian','easy','short','У меня на полке пять разных словарей, но я всегда пользуюсь одним и тем же.',NULL,NULL),
	 (183,'russian','easy','short','Какую из этих опер написал Бетховен: а) "Фиделио"; б) "Волшебная флейта"; в) "Весёлая вдова"?',NULL,NULL),
	 (184,'russian','easy','short','Он не может отличить вишнёвое дерево от сливового, но может назвать их на двенадцати языках.',NULL,NULL),
	 (185,'russian','easy','short','"Сколько километров до границы?" - "По дороге двадцать, а если напрямую, через болото, то километров пять".',NULL,NULL),
	 (186,'russian','easy','short','Всё пропало! Ты подписал документы, не проконсультировавшись с юристом. Ты хоть знаешь, что ты подписал?',NULL,NULL),
	 (187,'russian','easy','short','Если бы мы всегда отступали перед трудностями, мы бы до сих пор жили в пещерах.',NULL,NULL),
	 (188,'russian','easy','short','Том спит с ночником – не потому, что боится темноты, а потому что темнота его боится.',NULL,NULL),
	 (189,'russian','easy','short','По городу ты, может быть, и смог бы пройти незамеченным, но в деревне это невозможно.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (190,'russian','easy','short','Бронестекло обеспечивает безопасность, но из-за высокой цены пока не все могут себе его позволить.',NULL,NULL),
	 (191,'russian','easy','short','Извините, я хотел бы подержанный 250 кубовый мотоцикл тысяч за сто. У вас есть такой?',NULL,NULL),
	 (192,'russian','easy','short','Если мы не успеем сесть на самолёт в течение часа, то он улетит без нас.',NULL,NULL),
	 (193,'russian','easy','short','Надеюсь, у меня будет возможность вас увидеть, когда я в следующий раз буду в Бостоне.',NULL,NULL),
	 (194,'russian','easy','short','Где-то в этом лесу упал пассажирский самолёт. Нам необходимо найти его и помочь пострадавшим.',NULL,NULL),
	 (195,'russian','easy','short','Мне жаль тех людей, что пали в бою, но такова война. Она жестока и беспристрастна.',NULL,NULL),
	 (196,'russian','easy','short','К сожалению, познать все языки мира в совершенстве вам никогда не удастся. Их слишком много.',NULL,NULL),
	 (197,'russian','easy','short','Но на моём рисунке он, конечно, далеко не так хорош, как был на самом деле.',NULL,NULL),
	 (198,'russian','easy','short','Из-за солнца мы не видели и половины той красоты, что окружала нас на дороге.',NULL,NULL),
	 (199,'russian','easy','short','Солнечные лучи ослепили меня на мгновенье, но этого оказалось достаточно, чтобы я потерял своё преимущество.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (200,'russian','easy','short','Я увидел красивый дом из розового кирпича, с геранью в окнах и голубями на крыше.',NULL,NULL),
	 (201,'russian','easy','short','Если бы вы не сказали мне, чтобы я этого не делал, я бы это сделал.',NULL,NULL),
	 (202,'russian','easy','short','У меня скоро дедлайн, а я ничего не успел сделать. Мне приходится работать 25/8.',NULL,NULL),
	 (203,'russian','easy','short','"Что такое "альтернативная концовка"?" - "Это ещё одна концовка, которая чем-либо отличается от предыдущей".',NULL,NULL),
	 (204,'russian','easy','short','Мои соседи почему-то слишком не любят тишину. Они постоянно включают какую-нибудь громкую музыку.',NULL,NULL),
	 (205,'russian','easy','short','Белый дом рассматривает ряд краткосрочных мер, чтобы облегчить финансовую нагрузку на пострадавшие предприятия и рабочих.',NULL,NULL),
	 (206,'russian','easy','short','Если бы я ему это сказал, он бы никогда не согласился на такой огромный риск.',NULL,NULL),
	 (207,'russian','normal','medium','Самое положение буржуазии, как класса в капиталистическом обществе, неизбежно порождает её непоследовательность в демократическом перевороте. Самое положение пролетариата, как класса, заставляет его быть последовательным демократом.',NULL,NULL),
	 (208,'russian','normal','medium','Буржуазная революция безусловно необходима в интересах пролетариата. Чем полнее и решительнее, чем последовательнее будет буржуазная революция, тем обеспеченнее будет борьба пролетариата с буржуазией за социализм.',NULL,NULL),
	 (209,'russian','easy','short','Если я в папке с данными программы вместо её родного файла с пользовательскими данными помещу симлинк на нужный мне файл, это может поломать её работу?',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (210,'russian','easy','short','Сегодня после того, как я поехал в центр города, я встретился со своими друзьями в китайском ресторане, который находится в центре, и мы попили чай.',NULL,NULL),
	 (211,'russian','easy','short','В жизни не важно, кем человек является, что у него есть или как он выглядит. Важно - что он что-то делает, создает, меняет к лучшему.',NULL,NULL),
	 (212,'russian','easy','short','Я также не могу поверить в то, что куриное яйцо (или курица из яйца?) возникло случайно и эволюционировало путем медленного, постепенного и ненаправленного естественного отбора.',NULL,NULL),
	 (213,'russian','easy','short','Согласно Юджину Вигнеру, лауреату Нобелевской премии по физике, сознание человека может на самом деле "протянуть руку" - каким-то необъяснимым образом - и изменить физическое состояние системы.',NULL,NULL),
	 (214,'russian','normal','medium','Свои биометрические данные нельзя поменять и именно поэтому их нельзя использовать в качестве паролей, ведь, скомпрометировав их всего один раз, злоумышленник навсегда заполучит доступ ко всем вашим данным.',NULL,NULL),
	 (215,'russian','easy','short','У моих дедушки с бабушкой в саду живёт лисья семья, и дед повсюду установил камеры, чтобы их можно было снимать, в том числе ночью, когда они особенно активны.',NULL,NULL),
	 (216,'russian','easy','short','Порядок возникновения ключевых диезов такой - фа, до, соль, ре, ля, ми, си. А у ключевых бемолей он ровно противоположный, то есть - си, ми, ля, ре, соль, до, фа.',NULL,NULL),
	 (217,'russian','normal','medium','Исправить ошибочно написанное слово можно двумя способами. Первый, зачеркнуть его полностью и заново переписать или же зачеркнуть лишь часть с ошибкой и написать правильный вариант над перечёркнутой частью.',NULL,NULL),
	 (218,'russian','easy','short','Вы не должны спать при работающей угольной печи, потому что она даёт очень ядовитый газ, называемый окисью углерода. Сон при работающей угольной печи может привести к смерти.',NULL,NULL),
	 (220,'russian','easy','short','Иайдо - это путь меча, когда, будучи внезапно атакованным, ты способен быстро вытащить меч из ножен и одним его взмахом сразить своего противника, неважно, сидишь ты или стоишь.',NULL,NULL);
INSERT INTO texts (id,"language",difficulty,"length",content,"size","source") VALUES
	 (221,'russian','easy','short','В первые годы производства, Coca-Cola содержала кокаин. В 1914 году кокаин был классифицирован как наркотик, после чего при производстве Coca-Cola вместо него стали использовать кофеин.',NULL,NULL),
	 (222,'russian','easy','short','Отцы, живущие в городах, каждый день проводят восемь часов в офисе и ещё два тратят на дорогу на работу и обратно утром и вечером в переполненных электричках.',NULL,NULL),
	 (224,'english','easy','short','Iaido is a form of swordsmanship in which one strikes down an attacking opponent with one blow of the sword quickly drawn out of its sheath, whether the practitioner is sitting or walking.',NULL,NULL),
	 (225,'english','easy','short','In the first years that Coca-Cola was produced, it contained cocaine. In 1914, cocaine was classified as a narcotic, after which they used caffeine instead of cocaine in the production of Coca-Cola.',NULL,NULL),
	 (226,'english','easy','short','Fathers in cities spend eight hours in the office and another two hours traveling to and from their work on trains full of people every morning and evening.',NULL,NULL);
